from collections import deque

def find_components(grid, color):
    visited = [[False]*len(grid[0]) for _ in range(len(grid))]
    comps = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color and not visited[r][c]:
                comp = []
                queue = deque([(r,c)])
                visited[r][c] = True
                while queue:
                    cr, cc = queue.popleft()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == color and not visited[nr][nc]:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
                if len(comp) >= 2:
                    comps.append(comp)
    return comps

